<template>
  <div class="wrapper">
    <div class="line" @click="openMap">
      <div class="address-box">
        <span v-if=" address != '' ">{{address.address_name}}</span>
        <span v-else>请选择小区/大厦/标志建筑</span>
      </div>
      <i class="icon iconfont">&#xe655;</i>
    </div>
    <div class="line">
      <input class="detail" type="text" placeholder="请补充详细地址" v-model="detail" @blur="inputBlur('detail')">
    </div>
    <div class="line">
      <div class="user-box"><input type="text" placeholder="联系人" v-model="name" @blur="inputBlur('contactsName')"></div>
      <div class="phone-box">
        <input type="text" placeholder="手机号" v-model="phone" @focus="inputPhone" @input="inputPhone" @blur="inputBlur('contactsPhone')">
        <div class="phone-list" v-show="showPhoneList && phoneList.length > 0">
          <div class="item" v-for="(item, index) in phoneList" :key="index" @click="selectPhone(item)">{{item}}</div>
        </div>
      </div>
    </div>
    <div class="line mb10">
      <div class="sex-select" :class="{'active': sex == 1}" @click="selectSex(1)">
        <i class="icon iconfont no">&#xe615;</i>
        <i class="icon iconfont yes">&#xe660;</i>
        <span>先生</span>
      </div>
      <div class="sex-select" :class="{'active': sex == 2}" @click="selectSex(2)">
        <i class="icon iconfont no">&#xe615;</i>
        <i class="icon iconfont yes">&#xe660;</i>
        <span>女士</span>
      </div>
    </div>
    <div class="line">
      <div class="save-select" :class="{'active': isSave}" @click="selectSave">
        <i class="icon iconfont no">&#xe653;</i>
        <i class="icon iconfont yes">&#xe73b;</i>
        <span>保存到地址簿</span>
      </div>
    </div>

    <div class="confirm"><button class="btn" @click="confirm">确定</button></div>
  </div>
</template>

<script>
export default {
  name: 'AddAddress',
  data () {
    return {
      address: '',
      detail: '',
      name: '',
      phone: '',
      phoneList: [],
      showPhoneList: false,
      isSelectPhone: false,
      sex: 1, // 1先生 2女士
      isSave: false, // 是否选择了保存到地址簿按钮
      addressAddType: 1, // 1是快速添加地址 2从地址列表点击添加
      addressId: 0 // 地址ID
    }
  },
  created () {
    this.getPhoneList()

    this.address = this.$globalData.mapAddress

    let addressInput = this.$globalData.addressInput
    this.detail = addressInput.detail
    this.name = addressInput.name
    this.phone = addressInput.phone
    this.sex = addressInput.sex > 0 ? addressInput.sex : 1
    this.addressId = addressInput.adress_id

    if (!this.address && addressInput.adress) {
      this.address = addressInput
    }

    this.addressAddType = this.$globalData.addressAddType
    if (this.addressAddType == 2) {
      this.isSave = true
    }
  },
  methods: {
    // 点击确定按钮
    confirm () {
      var errorMsg = ''
      if (this.address == '') {
        errorMsg = '请选择位置'
      } else if (this.detail == '') {
        errorMsg = '请填写详细地址'
      } else if (this.name == '') {
        errorMsg = '请填写联系人'
      } else if (this.phone == '') {
        errorMsg = '请填写联系电话'
      }
      if (errorMsg != '') {
        this.$messagebox.alert(errorMsg)
        return
      }
      this.address.detail = this.detail
      this.address.name = this.name
      this.address.phone = this.phone
      this.address.sex = this.sex
      this.$globalData[this.$globalData.addressType] = this.address
      this.$globalData.addressInput = ''
      this.$globalData.mapAddress = ''
      if (this.isSave) {
        this.saveAddress()
      } else {
        this.$router.go(-this.addressAddType)
      }
    },
    async saveAddress () {
      try {
        let param = {
          adress: this.address.adress,
          detail: this.detail,
          name: this.name,
          latitude: this.address.point.lat,
          longitude: this.address.point.lng,
          sex: this.sex,
          phone: this.phone,
          adress_id: this.addressId
        }
        let res = await this.$api.saveAddress(param)
        this.$router.go(-this.addressAddType)
        console.log('3333', res)
      } catch (e) {
        console.log('保存地址发生错误 saveAddress', e)
      }
    },
    // 获取地址列表，提取手机号列表
    async getPhoneList () {
      try {
        let res = await this.$api.getAddressList({ longlatType: 'baidu' })
        if (res.errorMsg) {
          return
        }
        let phoneList = res.map(item => item.phone)
        let arr = []
        for (var i = 0; i < phoneList.length; i++) {
          if (arr.indexOf(phoneList[i]) == -1) {
            arr.push(phoneList[i])
          }
        }
        this.phoneList = arr
      } catch (e) {
        console.log('获取手机号列表出错 getPhoneList')
      }
    },
    // 跳转地图页面选择地址
    openMap () {
      this.$router.push('/openmap')
    },

    // 输入电话
    inputPhone () {
      if (this.phoneTimer) {
        clearTimeout(this.phoneTimer)
      }
      this.showPhoneList = (this.phone == '' || this.phone == undefined)
    },

    // 选择电话
    selectPhone (value) {
      this.phone = value
    },

    inputBlur (type) {
      if (this[type] != '' && this[type] != undefined) {
        this.savePageData()
      }
      this.phoneTimer = setTimeout(() => {
        this.showPhoneList = false
      }, 100)
    },

    savePageData () {
      var addressInput = {
        detail: this.detail,
        name: this.name,
        phone: this.phone,
        sex: this.sex,
        addressId: this.addressId
      }
      this.$globalData.addressInput = addressInput
    },

    // 选择性别
    selectSex (value) {
      this.sex = value
      this.savePageData()
    },

    // 选择保存到地址簿
    selectSave () {
      this.isSave = !this.isSave
    }
  }
}
</script>

<style lang="stylus" scoped>
  .wrapper
    .line
      height 50px
      line-height 50px
      background #fff
      font-size 16PX
      padding 0 10px
      border-bottom 1PX solid #efefef
      flexbox()
      .address-box, .detail, .user-box, .phone-box
        flex-grow 1
      .address-box
        ellipsis(1)
      .user-box
        padding-right 10px
      .phone-box
        border-left 1PX solid #efefef
        padding-left 10px
        position relative
        .phone-list
          background #fff
          position absolute
          left 0
          right -10px
          box-shadow -2px 3px 5px #ddd
          .item
            border-bottom 1PX solid #efefef
            padding 0 10px
            line-height 40px
            &:last-child
              border-bottom none
      .sex-select
        margin-right 30px
        .icon
          font-size 18px
          margin-right 8px
          vertical-align middle
        .no
          color #999
        .yes
          display none
        &.active
          .no
            display none
          .yes
            display inline-block
            color $color-main
      .save-select
        color #999
        .icon
          margin-right 8px
          font-size 18px
          vertical-align middle
        .yes
          display none
          color $color-main
        &.active
          color #333
          .no
            display none
          .yes
            display inline-block
    .confirm
      margin-top 50px
      text-align center
      .btn
        width 90%
        color #fff
        background $color-main
        font-size 18px
        line-height 2.4
        border-radius 2px
        &:active
          background darken($color-main, 10%)
</style>
